const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Washington state geometry
  const washington = ee.Geometry.Polygon([[
    [-124.8, 49.0],
    [-116.9, 49.0],
    [-116.9, 45.6],
    [-124.8, 45.6],
    [-124.8, 49.0]
  ]]);

  // Get SMAP soil moisture data
  const smap = ee.ImageCollection('NASA_USDA/HSL/SMAP10KM_soil_moisture');

  // Date 1: November 15, 2021
  const col1 = smap
    .filterDate('2021-11-14', '2021-11-16')
    .filterBounds(washington)
    .select('ssm'); // soil surface moisture

  const size1 = col1.size().getInfo();

  if (size1 === 0) {
    console.log('Nov 15 Images: 0');
    console.log('<answer>C1</answer>');
    return;
  }

  // Date 2: November 22, 2021
  const col2 = smap
    .filterDate('2021-11-21', '2021-11-23')
    .filterBounds(washington)
    .select('ssm');

  const size2 = col2.size().getInfo();

  if (size2 === 0) {
    console.log('Nov 22 Images: 0');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get mean images
  const img1 = col1.mean();
  const img2 = col2.mean();

  // Calculate mean soil moisture for Nov 15
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: washington,
    scale: 10000,
    maxPixels: 1e9
  });

  const moisture1 = stats1.get('ssm').getInfo();

  // Calculate pixel count for Nov 15
  const count1 = img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: washington,
    scale: 10000,
    maxPixels: 1e9
  }).get('ssm').getInfo();

  // Calculate mean soil moisture for Nov 22
  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: washington,
    scale: 10000,
    maxPixels: 1e9
  });

  const moisture2 = stats2.get('ssm').getInfo();

  // Calculate pixel count for Nov 22
  const count2 = img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: washington,
    scale: 10000,
    maxPixels: 1e9
  }).get('ssm').getInfo();

  // Validation
  if (count1 === 0 || count2 === 0) {
    console.log(`Nov 15 Pixels: ${count1}, Nov 22 Pixels: ${count2}`);
    console.log('<answer>C2</answer>');
    return;
  }

  if (moisture1 === null || moisture2 === null || 
      isNaN(moisture1) || isNaN(moisture2)) {
    console.log('Calculation resulted in NaN or null');
    console.log('<answer>C3</answer>');
    return;
  }

  // Output results
  console.log(`Nov 15, 2021: ${moisture1.toFixed(2)}% (Pixels: ${count1})`);
  console.log(`Nov 22, 2021: ${moisture2.toFixed(2)}% (Pixels: ${count2})`);

  // Determine answer
  if (moisture2 > moisture1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
